draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // two circles representing two people
  ctx.beginPath();
  ctx.arc(W/4 + 20*Math.sin(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W*3/4 + 20*Math.cos(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // lines representing connection between two people
  ctx.beginPath();
  ctx.moveTo(W/4 + 20*Math.sin(t), H/2);
  ctx.lineTo(W/2 + 10*Math.sin(2*t), H/2 + 10*Math.cos(2*t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W*3/4 + 20*Math.cos(t), H/2);
  ctx.lineTo(W/2 + 10*Math.sin(2*t), H/2 + 10*Math.cos(2*t));
  ctx.stroke();

  // two stick figures merging into one
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50 - 20*Math.sin(t));
  ctx.lineTo(W/2, H/2 + 50 + 20*Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70 - 20*Math.sin(t), 20, 0, 2*Math.PI);
  ctx.stroke();

  ctx.restore();
}
